  "rule_name": "rule_ffo4_total_receipts_table",
  "file": "/mnt/data/LSF/rules/officeqa/agentic_rule_full_data_gpt54mini/all_docs/q07_what_were_total_federal_receipts_for_the_fiscal_year_to_date/rule_ffo4_total_receipts_table.py",
  "code": "import re\n\n\ndef rule_ffo4_total_receipts_table(doc: dict) -> list[dict]:\n    try:\n        lines = doc.get(\"lines\") or []\n        if not lines:\n            return []\n\n        def norm(text: str) -> str:\n            return re.sub(r\"\\s+\", \" \", (text or \"\").strip()).lower()\n\n        def join_window(start: int, end: int) -> str:\n            parts = []\n            for i in range(max(0, start), min(len(lines), end)):\n                text = (lines[i].get(\"text\") or \"\").strip()\n                if text:\n                    parts.append(text)\n            return \"\\n\".join(parts).strip()\n\n        heading_idx = None\n        for idx, line in enumerate(lines):\n            low = norm(line.get(\"text\") or \"\")\n            if \"table ffo-4\" in low and \"summary of u.s. government receipts by source and outlays by agency\" in low:\n                heading_idx = idx\n                break\n        if heading_idx is None:\n            for idx, line in enumerate(lines):\n                low = norm(line.get(\"text\") or \"\")\n                if \"table ffo-4\" in low and \"summary of u.s. government receipts by source and outlays by\" in low:\n                    heading_idx = idx\n                    break\n        if heading_idx is None:\n            return []\n\n        results = []\n        search_limit = min(len(lines), heading_idx + 800)\n        for idx in range(heading_idx, search_limit):\n            low = norm(lines[idx].get(\"text\") or \"\")\n            if \"total receipts\" not in low:\n                continue\n            if not any(ch.isdigit() for ch in join_window(idx, min(len(lines), idx + 5))):\n                continue\n            window_start = max(0, idx - 1)\n            window_end = min(len(lines), idx + 5)\n            span_text = join_window(window_start, window_end)\n            if not span_text:\n                continue\n            span = {\"text\": span_text}\n            if lines[window_start].get(\"page_no\") is not None:\n                span[\"page_no\"] = lines[window_start].get(\"page_no\")\n            if lines[window_start].get(\"line_no\") is not None:\n                span[\"line_no\"] = lines[window_start].get(\"line_no\")\n            results.append(span)\n            break\n\n        return results\n    except Exception:\n        return []\n",
