  "code": "import re\n\n\ndef rule_total_federal_receipts_narrative(doc: dict) -> list[dict]:\n    try:\n        paragraphs = doc.get(\"paragraphs\") or []\n        lines = doc.get(\"lines\") or []\n\n        def norm(text: str) -> str:\n            return re.sub(r\"\\s+\", \" \", (text or \"\").strip()).lower()\n\n        def make_span(item: dict) -> dict:\n            span = {\"text\": item.get(\"text\") or \"\"}\n            if item.get(\"page_no\") is not None:\n                span[\"page_no\"] = item.get(\"page_no\")\n            if item.get(\"paragraph_no\") is not None:\n                span[\"paragraph_no\"] = item.get(\"paragraph_no\")\n            if item.get(\"line_no\") is not None:\n                span[\"line_no\"] = item.get(\"line_no\")\n            return span\n\n        for item in lines:\n            text = item.get(\"text\") or \"\"\n            low = norm(text)\n            if \"federal receipts\" not in low and \"total federal receipts\" not in low:\n                continue\n            if not any(key in low for key in (\"fytd\", \"fiscal year to date\", \"fiscal year-to-date\", \"fy 2024\", \"fy 2025\", \"fy 2023\")):\n                continue\n            if any(key in low for key in (\"were $\", \"totaled $\", \"jumped by $\", \"were up by $\", \"up by $\")):\n                return [make_span(item)]\n\n        for item in paragraphs:\n            text = item.get(\"text\") or \"\"\n            low = norm(text)\n            if \"federal receipts\" not in low and \"total federal receipts\" not in low:\n                continue\n            if not any(key in low for key in (\"fytd\", \"fiscal year to date\", \"fiscal year-to-date\", \"fy 2024\", \"fy 2025\", \"fy 2023\")):\n                continue\n            if any(key in low for key in (\"were $\", \"totaled $\", \"jumped by $\", \"were up by $\", \"up by $\")):\n                return [make_span(item)]\n\n        return []\n    except Exception:\n        return []\n",
